    const c = counts[d];
    if (c === 2 || c === 3) {
      repeatedCount++;
    } else if (c > 3) {
      return false;
    }
  }
  if (repeatedCount !== 1) {
    return false;
  }

  // Check digit (ISO 7064 MOD 11,10) over the first 10 digits
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (digits[i] + product) % 10;
    if (sum === 0) {
      sum = 10;
    }
